import{_ as s,o as a,c as t,a3 as o}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"路由与菜单","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/routing.md","filePath":"frontend/routing.md","lastUpdated":1786258579000}'),n={name:"frontend/routing.md"};function i(d,e,c,r,p,l){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="路由与菜单" tabindex="-1">路由与菜单 <a class="header-anchor" href="#路由与菜单" aria-label="Permalink to &quot;路由与菜单&quot;">​</a></h1><p>前端路由<strong>默认由后端菜单驱动</strong>——后端 <code>PageRegistry</code> 是菜单、路由、组件路径、权限码、i18n 键的单一事实源，前端只负责把菜单数据转成 <code>RouteRecordRaw</code> 并落地视图文件。本页讲这条链路怎么走通，以及卡住时怎么查。</p><h2 id="两种模式" tabindex="-1">两种模式 <a class="header-anchor" href="#两种模式" aria-label="Permalink to &quot;两种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>触发</th><th>行为</th></tr></thead><tbody><tr><td><strong>动态模式（默认）</strong></td><td>—</td><td>登录后拉 <code>/api/Auth/Permissions</code> 得到 <code>menus</code>，转成路由并 <code>addRoute</code></td></tr><tr><td>静态模式</td><td><code>VITE_AUTH_ROUTE_MODE === &#39;static&#39;</code></td><td>用前端静态路由 + <code>filterRoutesByPermission()</code> 按角色/权限过滤</td></tr></tbody></table><p>静态模式是兜底（后端不可用时的演示、纯前端调试），生产用动态模式。</p><h2 id="动态路由的生成链路" tabindex="-1">动态路由的生成链路 <a class="header-anchor" href="#动态路由的生成链路" aria-label="Permalink to &quot;动态路由的生成链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后端 PageRegistry（PageDescriptor + ButtonDescriptor）</span></span>
<span class="line"><span>   │  SaasMenuSeeder 播种（先查权限码，查不到就跳过并告警）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>SysMenu 表</span></span>
<span class="line"><span>   │  GET /api/Auth/Permissions → { roles, permissions, menus }</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>前端 mapMenuToRoutes()（packages/router/dynamic.ts）</span></span>
<span class="line"><span>   │  MenuRoute[] → RouteRecordRaw[]</span></span>
<span class="line"><span>   │  组件解析：后端 Component 路径 → 前端文件路径</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>router.addRoute(&#39;RootLayout&#39;, ...)</span></span></code></pre></div><h2 id="组件怎么解析" tabindex="-1">组件怎么解析 <a class="header-anchor" href="#组件怎么解析" aria-label="Permalink to &quot;组件怎么解析&quot;">​</a></h2><p>后端 <code>PageDescriptor.Component</code> 决定视图落点，前端有两条解析路径：</p><h3 id="一、常规页面-src-views-的-glob-匹配" tabindex="-1">一、常规页面：<code>src/views</code> 的 glob 匹配 <a class="header-anchor" href="#一、常规页面-src-views-的-glob-匹配" aria-label="Permalink to &quot;一、常规页面：\`src/views\` 的 glob 匹配&quot;">​</a></h3><p>约定 <strong><code>Component</code> = <code>Path</code> 去掉前导斜杠 + <code>/index</code></strong>：</p><table tabindex="0"><thead><tr><th>后端 <code>Path</code></th><th>后端 <code>Component</code></th><th>前端文件</th></tr></thead><tbody><tr><td><code>/identity/position</code></td><td><code>identity/position/index</code></td><td><code>src/views/identity/position/index.vue</code></td></tr><tr><td><code>/log/access</code></td><td><code>log/access/index</code></td><td><code>src/views/log/access/index.vue</code></td></tr></tbody></table><p><code>src/app/context.ts</code> 里用 <code>import.meta.glob(&#39;/src/views/**/*.vue&#39;)</code> 把所有视图收集起来，运行时按路径匹配。后端 <code>Component</code> 可能是 PascalCase，解析时会做大小写归一。</p><h3 id="二、-core-页面-corecomponentmap-显式登记" tabindex="-1">二、<code>_core</code> 页面：<code>coreComponentMap</code> 显式登记 <a class="header-anchor" href="#二、-core-页面-corecomponentmap-显式登记" aria-label="Permalink to &quot;二、\`_core\` 页面：\`coreComponentMap\` 显式登记&quot;">​</a></h3><p>个人中心、关于页等<strong>不落在 <code>src/views</code></strong> 的页面（源码在 <code>packages/views/_core/</code>），<code>Component</code> 写成 <code>_core/xxx/index</code>，由 <code>packages/router/dynamic.ts</code> 的 <code>coreComponentMap</code> 解析：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> coreComponentMap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;_core/about/index&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;~/views/_core/about/index.vue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;_core/profile/index&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;~/views/_core/profile/index.vue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">新增 <code>_core</code> 页面必须同时登记</p><p>只放视图文件而不在 <code>coreComponentMap</code>（以及 <code>componentAliasMap</code>）登记，动态路由匹配不到组件，会<strong>回退到 not-found</strong>。表现是「菜单有、点进去 404」。</p></div><h2 id="路由守卫" tabindex="-1">路由守卫 <a class="header-anchor" href="#路由守卫" aria-label="Permalink to &quot;路由守卫&quot;">​</a></h2><p><code>setupRouterGuard(router)</code>（<code>packages/router/guard.ts</code>）在 <code>beforeEach</code> 里依次做：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 无 token                    → 跳登录页</span></span>
<span class="line"><span>2. 用户上下文失效              → 重新拉取用户信息 + 权限</span></span>
<span class="line"><span>3. 路由未加载                  → 装载动态/静态路由 + 拉取用户偏好</span></span>
<span class="line"><span>4. meta.roles / meta.permissions 校验  → 无权跳 403</span></span>
<span class="line"><span>5. 维护标签栏（多标签页状态）</span></span></code></pre></div><p>第 3 步是<strong>只做一次</strong>的：路由装载完成后打标记，后续导航不再重复请求。因此「登录后第一次跳转」比后续慢是正常的。</p><h2 id="静态公共页" tabindex="-1">静态公共页 <a class="header-anchor" href="#静态公共页" aria-label="Permalink to &quot;静态公共页&quot;">​</a></h2><p>纯静态的公共页（登录页、错误页、<code>/control-center</code>、<code>/editor-demo</code> 等）<strong>不登记在 <code>PageRegistry</code></strong>，由前端 <code>src/router/routes.ts</code> 持有（认证页与错误页定义在 <code>packages/router/routes/core.ts</code>，由 <code>routes.ts</code> 展开），经 <code>app/context.ts</code> 注册进 app-context。</p><p>判断标准：需要权限控制、需要出现在侧边菜单里的 → 后端登记；纯展示、所有人可见的 → 前端静态路由。</p><h2 id="菜单文案" tabindex="-1">菜单文案 <a class="header-anchor" href="#菜单文案" aria-label="Permalink to &quot;菜单文案&quot;">​</a></h2><p><code>PageDescriptor.I18nKey</code> 的命名规则是 <strong><code>menu.{Code 中的 . 与 - 替换为 _}</code></strong>：</p><table tabindex="0"><thead><tr><th>页面码</th><th><code>I18nKey</code></th><th>前端语言包的键</th></tr></thead><tbody><tr><td><code>identity.position</code></td><td><code>menu.identity_position</code></td><td><code>identity_position</code></td></tr><tr><td><code>log.permission-change</code></td><td><code>menu.log_permission_change</code></td><td><code>log_permission_change</code></td></tr></tbody></table><p>文案维护在 <code>packages/locales/langs/{zh-CN,en-US}/menu.ts</code>，键是去掉 <code>menu.</code> 前缀后的部分。缺文案时会回退显示键名——看到侧边栏出现 <code>menu.xxx</code> 字样就是漏了这一步。</p><h2 id="多标签页" tabindex="-1">多标签页 <a class="header-anchor" href="#多标签页" aria-label="Permalink to &quot;多标签页&quot;">​</a></h2><p>守卫维护标签栏状态。<code>PageDescriptor.IsAffix: true</code> 的页面是<strong>固定标签</strong>（如仪表盘），不可关闭。</p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>查什么</th></tr></thead><tbody><tr><td>菜单不显示</td><td>后端：权限码是否已落库（<code>SaasMenuSeeder</code> <strong>查不到权限就跳过并告警</strong>）；当前用户是否有该权限码</td></tr><tr><td>菜单有、点进去 404</td><td>视图文件路径是否与 <code>Component</code> 约定一致；<code>_core</code> 页面是否登记了 <code>coreComponentMap</code></td></tr><tr><td>侧边栏显示 <code>menu.xxx</code></td><td><code>menu.ts</code> 漏了对应文案</td></tr><tr><td>刷新后路由丢失</td><td>路由是 <code>addRoute</code> 动态加的，刷新会重新走守卫装载——若一直 404，看第 2/3 步是否因接口失败中断</td></tr><tr><td>无权页面还能进</td><td>检查 <code>PageDescriptor.PermissionCode</code> 是否为空（空 = 纯展示菜单，不做门控）</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../backend/introduction#菜单-后端单一事实源">后端架构 · 菜单</a>：<code>PageRegistry</code> 的字段与种子机制</li><li><a href="./permission">权限与脱敏</a>：三级权限过滤</li><li><a href="./schema-page">Schema 驱动页面</a>：页面本身怎么写</li><li><a href="./../backend/development#配方-c-加一个前端页面">二次开发 · 加一个前端页面</a>：端到端清单</li></ul>`,34)])])}const g=s(n,[["render",i]]);export{k as __pageData,g as default};
